from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class PlanActivateOperationStatusASMV1(SchemaObject):
    plan_id = SchemaField(name='cmPlanId', optional=True)
    action_id = SchemaField(name='id', not_null=True)
    links = SchemaField(name="links", optional=True)
    status = SchemaField(name='status', not_null=True)
    error_message = SchemaField(name='errorMessage', optional=True)

    def __init__(self, plan_id, action_id, links, status, error_message):
        self.plan_id = plan_id
        self.action_id = action_id
        self.links = links
        self.status = status
        self.error_message = error_message

        super(PlanActivateOperationStatusASMV1, self).__init__()
